/** Source-defined lifecycle controls. All output remains bounded engineering evidence. */
export const LIFECYCLE_VERSION='forge-lifecycle/2';
export const LIFECYCLE_IDS=['X08','X09','X10','X11','X12','X13','X17','X18','X19','X20','X21','X22','X23','X26','X27','X31','X36','X37','X38','X39','X40','X41','X42','X43','X44','X45','X46','X53','X54','X55','X56','X57','X58','X61','X64','X65'];
