const TYPES=['product','substance','site','material','process','method','specification','batch','equipment'];
const SECTIONS=/^(2\.3(?:\.[SP](?:\.\d{1,2})*)?|3\.2\.[SP](?:\.\d{1,2})*)$/;
const OPS=new Set(['ALL_APPROVED','NO_OPEN_CONFLICTS','HAS_SOURCE_CONTEXT','REQUIRED_PARAMETER','SOURCE_REVISION_CURRENT']);
const RELATIONS={RAW_MATERIAL_TO_INTERMEDIATE:['material','material'],INTERMEDIATE_TO_BATCH:['material','batch'],BATCH_TO_FINISHED_PRODUCT:['batch','product'],PROCESS_STEP_TO_CPP:['process','specification'],PROCESS_STEP_TO_CQA:['process','specification'],USES_EQUIPMENT:['process','equipment'],AT_SITE:['process','site'],USES_MATERIAL:['process','material'],USES_METHOD:['process','method'],HAS_SPECIFICATION:['product','specification'],PROCESS_STEP_TO_STEP:['process','process']};
const AUTHOR_ROLES=['owner','admin','author'];
const REVIEW_ROLES=['owner','reviewer','approver'];
const DENY_KEYS=new Set(['__proto__','constructor','prototype']);
const fail=(code,msg,status=400)=>{throw new ForgeError(code,msg,status);};
const copy=x=>structuredClone(x);
function text(x,label,max=500){if(typeof x!=='string'||!x.trim()||x.length>max)fail('LIFECYCLE_INPUT',`${label} is required and must fit ${max} characters.`);return x.trim();}
function list(x,label,max=100){if(!Array.isArray(x)||x.length>max)fail('LIFECYCLE_INPUT',`${label} must be an array with at most ${max} entries.`);return x;}
function schema(x,allowed){if(!x||typeof x!=='object'||Array.isArray(x))fail('LIFECYCLE_INPUT','Use a structured lifecycle operation.');for(const k of Object.keys(x))if(DENY_KEYS.has(k)||!allowed.includes(k))fail('LIFECYCLE_SCHEMA',`Unsupported lifecycle property: ${k}. Scientific properties must be exact source/fact references.`);}
function integer(x,label,min=0,max=1000000){if(!Number.isSafeInteger(x)||x<min||x>max)fail('LIFECYCLE_INPUT',`${label} is outside supported integer bounds.`);return x;}
function enumValue(x,values,label){if(!values.includes(x))fail('LIFECYCLE_INPUT',`Unsupported ${label}.`);return x;}
function section(x){const v=text(x,'CTD section',40);if(!SECTIONS.test(v))fail('LIFECYCLE_INPUT','Use a supported Module 2.3 or 3.2.S / 3.2.P section identifier.');return v;}
function role(actor,roles){if(!actor?.id)fail('UNAUTHENTICATED','A verified workspace principal is required.',401);if(!roles.includes(actor.role))fail('FORBIDDEN','Your workspace role cannot perform this lifecycle operation.',403);}
export function hydrateLifecycle(state){state.ext??={};state.ext.lifecycle??={version:LIFECYCLE_VERSION,decisions:[],invalidations:[]};const e=state.ext.lifecycle;if(e.version!==LIFECYCLE_VERSION)fail('LIFECYCLE_VERSION','This lifecycle schema needs an explicit migration.',409);for(const c of COLLECTIONS)e[c]??=[];return e;}
function all(state){const e=hydrateLifecycle(state);return COLLECTIONS.flatMap(c=>e[c].map(x=>({...x,collection:c})));}
function found(state,id){const x=all(state).find(x=>x.id===id);if(!x)fail('LIFECYCLE_NOT_FOUND','The lifecycle record is unavailable in this authorized workspace.',404);return x;}
function latest(state,x){return !hydrateLifecycle(state)[x.collection].some(y=>y.logicalId===x.logicalId&&y.revision>x.revision);}
function src(state,id,requireText=false){const s=state.sources.find(x=>x.id===id);if(!s)fail('EVIDENCE_SOURCE','Source does not exist in this workspace.',404);if(['SUPERSEDED','SOURCE_FAILED','REJECTED'].includes(s.status))fail('STALE_EVIDENCE','Use a current non-failed source revision.',409);if(!s.permission||!s.hash||!Number.isInteger(s.version))fail('EVIDENCE_SOURCE','Source permission, integrity hash and revision are required.',409);if(requireText&&(!s.text||typeof s.text!=='string'))fail('SOURCE_TEXT_REQUIRED','A preserved original text span is required for this control.',409);return s;}
function fact(state,ref,{approved=true}={}){schema(ref,['fieldId','revision']);const f=state.fields.find(x=>x.id===ref.fieldId);if(!f)fail('EVIDENCE_FACT','Fact does not exist in this workspace.',404);if(ref.revision!==f.revision)fail('STALE_EVIDENCE','The exact fact revision changed.',409);const s=src(state,f.sourceId);if(s.hash!==f.sourceHash||s.version!==f.sourceVersion||s.status!=='PARSED'||!f.span?.raw)fail('STALE_EVIDENCE','Fact must bind the exact parsed source hash, revision and span.',409);if(['STALE','REJECTED','MISSING'].includes(f.status)||(approved&&f.status!=='APPROVED'))fail('UNAPPROVED_EVIDENCE','Current approved facts are required.',409);if(f.value===null||!Number.isFinite(f.value))fail('EVIDENCE_FACT','Numeric evidence cannot be invented or non-finite.',409);return f;}
function refs(state,input,required=true){const a=list(input||[],'Evidence refs');if(required&&!a.length)fail('EVIDENCE_REQUIRED','At least one current source-backed fact revision is required.',409);const seen=new Set();return a.map(r=>{const f=fact(state,r);if(seen.has(f.id))fail('DUPLICATE_EVIDENCE','A fact cannot be repeated to inflate coverage.');seen.add(f.id);return {fieldId:f.id,revision:f.revision,sourceId:f.sourceId,sourceVersion:f.sourceVersion,sourceHash:f.sourceHash,value:f.value,unit:f.unit,parameter:f.parameter,product:f.product,facility:f.facility,batch:f.batch,method:f.method,basis:f.basis,condition:f.condition,low:f.low,high:f.high,span:copy(f.span)};});}
function citations(state,input,required=false){const a=list(input||[],'Source citations',20);if(required&&!a.length)fail('CITATION_REQUIRED','An exact preserved source excerpt is required.',409);return a.map(r=>{schema(r,['sourceId','version','start','end','hash']);const s=src(state,r.sourceId,true);if(r.version!==s.version||r.hash&&r.hash!==s.hash)fail('STALE_EVIDENCE','Citation must match the current exact source revision.',409);const start=integer(r.start,'Citation start',0,s.text.length),end=integer(r.end,'Citation end',1,s.text.length);if(end<=start||end-start>6000)fail('CITATION_BOUNDS','Use a non-empty bounded original source excerpt.');return {sourceId:s.id,sourceVersion:s.version,sourceHash:s.hash,start,end,raw:s.text.slice(start,end),offsetKind:'UTF-16 character offsets'};});}
function dependencies(state,ids=[],approved=true){return list(ids,'Dependencies').map(id=>{const x=found(state,id);if(!latest(state,x)||effectiveStatus(state,x.id)==='STALE')fail('STALE_DEPENDENCY','A dependency has a new or stale revision.',409);if(approved&&effectiveStatus(state,x.id)!=='APPROVED')fail('UNAPPROVED_DEPENDENCY','An independent approval of the exact dependency revision is required.',409);return {id:x.id,revision:x.revision,digest:x.digest};});}
function currentProblems(state,x,seen=new Set()){if(seen.has(x.id))return ['DEPENDENCY_CYCLE'];seen.add(x.id);const issues=[];if(!latest(state,x))issues.push('SUPERSEDED_RECORD');if(hydrateLifecycle(state).invalidations.some(i=>i.recordId===x.id))issues.push('INVALIDATED_DEPENDENCY');for(const r of x.evidenceRefs||[])try{const f=fact(state,{fieldId:r.fieldId,revision:r.revision});if(f.value!==r.value||f.unit!==r.unit||f.sourceHash!==r.sourceHash||f.sourceVersion!==r.sourceVersion)issues.push('EVIDENCE_BINDING_MISMATCH');}catch(e){issues.push(e.code);}for(const c of x.citations||[])try{const s=src(state,c.sourceId,true);if(s.version!==c.sourceVersion||s.hash!==c.sourceHash||s.text.slice(c.start,c.end)!==c.raw)issues.push('STALE_CITATION');}catch(e){issues.push(e.code);}for(const d of x.dependencies||[]){try{const dep=found(state,d.id);if(dep.digest!==d.digest||dep.revision!==d.revision||currentProblems(state,dep,new Set(seen)).length)issues.push('STALE_DEPENDENCY');const decision=hydrateLifecycle(state).decisions.findLast(y=>y.targetId===dep.id&&y.digest===dep.digest&&y.revision===dep.revision);if(x.collection!=='branches'&&d.approvalRequired!==false&&decision?.choice!=='APPROVE')issues.push('DEPENDENCY_DECISION_CHANGED');}catch(e){issues.push(e.code);}}if(x.draftId){const draft=state.drafts.find(d=>d.id===x.draftId);if(!draft||draft.revision!==x.draftRevision||draft.status!=='APPROVED'||JSON.stringify(draft.statements)!==JSON.stringify(x.statements))issues.push('STALE_DRAFT');}for(const r of x.candidateRefs||[])try{fact(state,{fieldId:r.fieldId,revision:r.revision},{approved:false});}catch(e){issues.push(e.code);}return [...new Set(issues)];}
export function effectiveStatus(state,id){const x=found(state,id);if(currentProblems(state,x).length)return 'STALE';const d=hydrateLifecycle(state).decisions.findLast(y=>y.targetId===id&&y.digest===x.digest&&y.revision===x.revision);return d?{APPROVE:'APPROVED',REJECT:'REJECTED',REQUEST_EVIDENCE:'NEEDS_REVIEW',REVISE:'NEEDS_REVIEW'}[d.choice]:'CANDIDATE';}
function project(state,x){return {...copy(x),status:effectiveStatus(state,x.id),issues:currentProblems(state,x),humanAuthority:false};}
async function append(state,collection,body,input,actor){const e=hydrateLifecycle(state);if(all(state).length>=1500)fail('LIFECYCLE_LIMIT','The bounded workspace lifecycle limit is 1500 versions.',413);let prior;if(input.predecessorId){prior=found(state,input.predecessorId);if(prior.collection!==collection||!latest(state,prior))fail('PREDECESSOR_REVISION','Supersede only the latest version in the same record collection.',409);}const record={id:uid(collection.slice(0,10)),logicalId:prior?.logicalId||uid('controlled'),revision:prior?prior.revision+1:1,predecessorId:prior?.id||null,createdBy:actor.id,createdAt:now(),workflowVersion:LIFECYCLE_VERSION,inputWorkspaceRevision:state.version,status:'CANDIDATE',evidenceRefs:[],citations:[],dependencies:[],...body};record.digest=await hash(JSON.stringify(record));e[collection].push(record);return record;}
function supportedLabel(label,evidence,cites){const v=text(label,'Source-backed object label',160);const terms=evidence.flatMap(f=>[f.parameter,f.batch,f.method,f.product,f.facility]).filter(Boolean);if(!terms.includes(v)&&!cites.some(c=>c.raw.includes(v)))fail('UNSUPPORTED_LABEL','Object identity must occur in cited source text or exact fact metadata.');return v;}
function descriptor(state,r){const f=fact(state,{fieldId:r.fieldId,revision:r.revision});return {fieldId:f.id,revision:f.revision,parameter:f.parameter,value:f.value,unit:f.unit,batch:f.batch,method:f.method,basis:f.basis,condition:f.condition,low:f.low,high:f.high,sourceId:f.sourceId,sourceVersion:f.sourceVersion,sourceHash:f.sourceHash,product:f.product,facility:f.facility,timePoint:f.timePoint??null,timeUnit:f.timeUnit||''};}
function context(f){return JSON.stringify([f.parameter,f.product,f.method,f.unit,f.low,f.high,f.condition,f.basis]);}
function comparable(fs){const ok=fs.length>1&&fs.every(f=>f.product&&f.method&&f.unit&&f.condition&&f.basis)&&new Set(fs.map(context)).size===1;const values=fs.map(x=>x.value),n=values.length,mean=n?values.reduce((a,b)=>a+b,0)/n:null;return {comparable:ok,n,minimum:ok?Math.min(...values):null,maximum:ok?Math.max(...values):null,mean:ok?mean:null,sampleSD:ok&&n>1?Math.sqrt(values.reduce((s,x)=>s+(x-mean)**2,0)/(n-1)):null,reason:ok?'Recorded parameter, product, method, unit, limits, condition and basis match.':'At least two records with equal recorded method, unit, limits, condition and basis are required.',interpretation:'Descriptive recorded evidence only; no product disposition, equivalence or scientific qualification.'};}
function ruleCheck(state,rule){const fs=state.fields.filter(f=>f.status==='APPROVED'&&!(()=>{try{fact(state,{fieldId:f.id,revision:f.revision});return false;}catch{return true;}})());let passed=false,evidence=[];const expr=rule.expression;switch(expr.op){case 'ALL_APPROVED':evidence=rule.evidenceRefs.map(r=>r.fieldId);passed=rule.evidenceRefs.length>0&&currentProblems(state,rule).length===0;break;case 'NO_OPEN_CONFLICTS':evidence=state.conflicts.filter(c=>c.status==='OPEN').map(c=>c.id);passed=!evidence.length;break;case 'HAS_SOURCE_CONTEXT':evidence=fs.filter(f=>rule.parameters.includes(f.parameter)&&f.method&&f.unit&&f.basis&&f.condition).map(f=>f.id);passed=rule.parameters.every(p=>fs.some(f=>f.parameter===p&&f.method&&f.unit&&f.basis&&f.condition));break;case 'REQUIRED_PARAMETER':evidence=fs.filter(f=>rule.parameters.includes(f.parameter)).map(f=>f.id);passed=rule.parameters.every(p=>fs.filter(f=>f.parameter===p).length>=expr.count);break;case 'SOURCE_REVISION_CURRENT':evidence=rule.evidenceRefs.map(r=>r.fieldId);passed=!currentProblems(state,rule).length;break;}
return {ruleId:rule.id,revision:rule.revision,digest:rule.digest,operator:expr.op,passed,evidence,authority:'LOCAL_APPROVED_CONTROL_ONLY',interpretation:'A passed technical check is not regulatory acceptance or validation.'};}
function requirementCoverage(state,record){const fs=(record.evidenceRefs||[]).map(r=>{try{return fact(state,{fieldId:r.fieldId,revision:r.revision});}catch{return null;}}).filter(Boolean);const reqs=(record.requirementIds||[]).map(id=>found(state,id));return reqs.map(req=>{const matching=fs.filter(f=>f.parameter===req.parameter);return {requirementId:req.id,revision:req.revision,parameter:req.parameter,requiredCount:req.minCount,availableCount:matching.length,covered:effectiveStatus(state,req.id)==='APPROVED'&&record.market===req.market&&matching.length>=req.minCount&&req.sections.some(s=>record.section===s||record.section?.startsWith(s+'.')),fieldIds:matching.map(f=>f.id),sourceCitations:req.citations,legalConclusion:false};});}
