function selected(state,c){const a=hydrateLifecycle(state)[c].map(x=>({...x,collection:c}));return a.filter(x=>latest(state,x)).map(x=>project(state,x));}
function rawRefs(records){return [...new Map(records.flatMap(x=>x.evidenceRefs||[]).map(r=>[`${r.fieldId}@${r.revision}`,{fieldId:r.fieldId,revision:r.revision}])).values()];}
function closureChecks(state,x){return x.expectedChecks.map(check=>{try{const expected=fact(state,check.expected),actual=fact(state,check.actual);const sameContext=context(expected)===context(actual);let passed=check.operator==='CURRENT_APPROVED'||check.operator==='EQUAL'&&sameContext&&actual.value===expected.value||check.operator==='CONTEXT_MATCH'&&sameContext||check.operator==='WITHIN_RECORDED_LIMITS'&&sameContext&&(expected.low!==null||expected.high!==null)&&(expected.low===null||actual.value>=expected.low)&&(expected.high===null||actual.value<=expected.high);return {...check,passed,expectedValue:expected.value,actualValue:actual.value,unit:actual.unit,sourceId:actual.sourceId,sourceHash:actual.sourceHash,reason:passed?'Exact current source-backed check passed.':'Recorded actual evidence does not meet this controlled expected check.'};}catch(e){return {...check,passed:false,reason:e.code};}});}
