/** The graph distinguishes causal dependencies from semantic genealogy and version history. */
export function lifecycleGraph(state){
 const nodes=[],edges=[],records=all(state),seen=new Set();
 for(const s of state.sources){nodes.push({id:s.id,type:"source",label:s.name,status:s.status});seen.add(s.id);}
 for(const f of state.fields){nodes.push({id:f.id,type:"fact",label:`${f.parameter} · ${f.batch}`,status:f.status});seen.add(f.id);edges.push({from:f.sourceId,to:f.id,reason:"exact source span",dependency:true});}
 for(const d of state.drafts){nodes.push({id:d.id,type:"draft",label:d.title,status:d.status});seen.add(d.id);for(const id of d.fieldIds)edges.push({from:id,to:d.id,reason:"statement evidence",dependency:true});}
 for(const d of state.decisions){nodes.push({id:d.id,type:"decision",label:d.action,status:d.status});seen.add(d.id);edges.push({from:d.targetId,to:d.id,reason:"revision-bound decision",dependency:true});}
 for(const x of state.exports){nodes.push({id:x.id,type:"export",label:x.name,status:x.status});seen.add(x.id);edges.push({from:x.draftId,to:x.id,reason:"approved snapshot",dependency:true});}
 const node=(id,type,label,status)=>{if(!seen.has(id)){nodes.push({id,type,label,status});seen.add(id);}};
 for(const x of records){node(x.id,x.collection,x.label||x.id,effectiveStatus(state,x.id));for(const r of x.evidenceRefs||[])edges.push({from:r.fieldId,to:x.id,reason:'exact approved fact revision',dependency:true,revision:r.revision,sourceHash:r.sourceHash});for(const c of x.citations||[])edges.push({from:c.sourceId,to:x.id,reason:'exact source excerpt',dependency:true,sourceHash:c.sourceHash});for(const d of x.dependencies||[])edges.push({from:d.id,to:x.id,reason:'exact controlled record revision',dependency:true,revision:d.revision,digest:d.digest});for(const r of x.candidateRefs||[])edges.push({from:r.fieldId,to:x.id,reason:'proposed candidate evidence in simulation',dependency:true,revision:r.revision});if(x.predecessorId)edges.push({from:x.predecessorId,to:x.id,reason:'immutable predecessor history',dependency:false});if(x.draftId)edges.push({from:x.draftId,to:x.id,reason:'exact approved draft revision',dependency:true,revision:x.draftRevision});if(x.collection==='relations')edges.push({from:x.fromId,to:x.toId,via:x.id,reason:x.relationType,dependency:false});if(x.collection==='branches')edges.push({from:x.sourceId,to:x.id,reason:'source change simulation',dependency:true});}
 for(const d of hydrateLifecycle(state).decisions){node(d.id,'lifecycle-decision',d.choice,effectiveStatus(state,d.targetId)==='STALE'?'STALE':'HISTORICAL_DECISION');edges.push({from:d.targetId,to:d.id,reason:'revision-bound human decision',dependency:true,revision:d.revision,digest:d.digest});}
 for(const q of state.queries||[]){node(q.id,'haq',q.title,q.status);for(const id of q.fieldIds||[])edges.push({from:id,to:q.id,reason:'HA response evidence',dependency:true});}
 for(const a of state.actions||[]){node(a.id,'action',a.title,a.status);for(const id of a.sourceIds||[])edges.push({from:id,to:a.id,reason:'source-backed closure dependency',dependency:true});}
 if(nodes.length>10000||edges.length>30000)fail('GRAPH_LIMIT','Recorded dependency graph exceeds supported bounded workspace limits.',413);
 return {nodes,edges,revision:state.version,workflowVersion:LIFECYCLE_VERSION,scope:'Recorded authorized workspace dependencies; absence of a path is not scientific or legal proof of universal non-impact.'};
}
function impactFor(state,rootId){const graph=lifecycleGraph(state);if(!graph.nodes.some(n=>n.id===rootId))fail('IMPACT_ROOT','Select an existing source, fact, rule or controlled object.',404);const included=new Set([rootId]),parents=new Map();let again=true;while(again){again=false;for(const e of graph.edges)if(e.dependency&&included.has(e.from)&&!included.has(e.to)){included.add(e.to);parents.set(e.to,e);again=true;}}return {rootId,graphRevision:graph.revision,included:graph.nodes.filter(n=>included.has(n.id)).map(n=>({...n,pathReason:parents.get(n.id)||null})),excluded:graph.nodes.filter(n=>!included.has(n.id)).map(n=>({...n,proof:{type:'NO_RECORDED_DEPENDENCY_PATH',rootId,graphRevision:graph.revision,workflowVersion:LIFECYCLE_VERSION},reason:'No causal dependency path in this exact recorded graph; external or unrecorded scientific relationships remain unknown.'})),globalNonImpactClaim:false};}
/** Append invalidations; scientific records and past decision payloads are never rewritten. */
export function invalidateLifecycle(state,sourceId){const e=hydrateLifecycle(state),impact=impactFor(state,sourceId),ids=new Set(impact.included.map(x=>x.id)),invalidated=[];for(const x of all(state).filter(x=>ids.has(x.id))){if(!e.invalidations.some(i=>i.recordId===x.id&&i.sourceId===sourceId)){if(e.invalidations.length>=3000)fail('LIFECYCLE_LIMIT','Invalidation history limit reached.',413);const i={id:uid('invalidate'),recordId:x.id,revision:x.revision,digest:x.digest,sourceId,at:now(),reason:'DEPENDENCY_SOURCE_CHANGED',priorStatus:effectiveStatus(state,x.id),closureStatus:x.collection==='closures'?'REOPENED':null};e.invalidations.push(i);invalidated.push(i);}}return {sourceId,invalidated,impact,selective:true,historyRewritten:false};}
function stabilityTrends(state){const obs=selected(state,'observations').filter(o=>o.status==='APPROVED'),entries=[];for(const o of obs)for(const r of o.measurementRefs){try{const f=fact(state,r);entries.push({observationId:o.id,batchId:o.batchId,time:o.recordedTime,timeUnit:o.timeUnit,...descriptor(state,r),key:JSON.stringify([o.batchId,f.parameter,f.method,f.unit,f.low,f.high,f.condition,f.basis,o.timeUnit])});}catch{}}
 return [...Map.groupBy(entries,e=>e.key)].map(([,group])=>{const samples=group.sort((a,b)=>a.time-b.time),uniqueTimes=new Set(samples.map(s=>s.time)),n=samples.length,mean=n?samples.reduce((s,x)=>s+x.value,0)/n:null,meanTime=n?samples.reduce((s,x)=>s+x.time,0)/n:null,den=samples.reduce((s,x)=>s+(x.time-meanTime)**2,0),slope=n>1&&uniqueTimes.size===n&&den>0?samples.reduce((s,x)=>s+(x.time-meanTime)*(x.value-mean),0)/den:null;return {batchId:samples[0].batchId,parameter:samples[0].parameter,method:samples[0].method,condition:samples[0].condition,unit:samples[0].unit,timeUnit:samples[0].timeUnit,samples,n,minimum:Math.min(...samples.map(x=>x.value)),maximum:Math.max(...samples.map(x=>x.value)),mean,descriptiveSlope:slope,duplicateTimes:uniqueTimes.size!==n,extrapolation:false,predictedShelfLife:null,interpretation:'Slope describes only approved observed points in the exact recorded time unit. No extrapolation, shelf-life assignment or stability acceptance.'};});}
function dossierConsistency(state){const records=selected(state,'dossiers').filter(d=>d.status!=='STALE'),entries=records.flatMap(d=>d.facts.map(f=>({...f,dossierId:d.id,section:d.section,market:d.market,productId:d.productId})));return [...Map.groupBy(entries,f=>JSON.stringify([f.productId,f.batch,f.parameter]))].map(([key,items])=>({key,parameter:items[0].parameter,batch:items[0].batch,items,scientificValueConflict:new Set(items.map(x=>JSON.stringify([x.value,x.unit]))).size>1,contextConflict:new Set(items.map(x=>JSON.stringify([x.method,x.low,x.high,x.condition,x.basis]))).size>1,sectionCoverage:[...new Set(items.map(x=>x.section))],interpretation:'Cross-dossier evidence/context check; differences require qualified review.'}));}
function specifications(state){const fs=state.fields.filter(f=>f.status==='APPROVED').filter(f=>{try{fact(state,{fieldId:f.id,revision:f.revision});return true;}catch{return false;}});return [...Map.groupBy(fs,f=>JSON.stringify([f.product,f.parameter]))].map(([,items])=>({parameter:items[0].parameter,product:items[0].product,specificationProfiles:[...new Map(items.map(f=>[JSON.stringify([f.method,f.unit,f.low,f.high,f.basis,f.condition]),{method:f.method,unit:f.unit,low:f.low,high:f.high,basis:f.basis,condition:f.condition,fieldIds:items.filter(x=>context(x)===context(f)).map(x=>x.id),sourceVersions:items.filter(x=>context(x)===context(f)).map(x=>({sourceId:x.sourceId,version:x.sourceVersion,hash:x.sourceHash}))}])).values()],contextConflict:new Set(items.map(context)).size>1,interpretation:'Different recorded profiles are a review flag, not automatic non-compliance.'}));}
function structural(state,d){const coverage=requirementCoverage(state,d),issues=currentProblems(state,d);if(!d.requirementIds.length)issues.push('REQUIREMENT_PROFILE_NOT_CONFIGURED');if(coverage.some(c=>!c.covered))issues.push('REQUIRED_CONTENT_GAP');for(const id of d.blockIds){const block=found(state,id);if(!block.evidenceRefs.every(r=>d.evidenceRefs.some(f=>f.fieldId===r.fieldId&&f.revision===r.revision)))issues.push('BLOCK_DOSSIER_EVIDENCE_MISMATCH');}return {dossierId:d.id,revision:d.revision,section:d.section,coverage,issues:[...new Set(issues)],passed:!issues.length,technicalScope:'Declared controlled section and requirement profile only',eCTDConformance:false};}
function marketMatrix(state){const dossiers=selected(state,'dossiers');return [...Map.groupBy(dossiers,d=>`${d.productId}|${d.market}`)].map(([key,ds])=>({key,productId:ds[0].productId,market:ds[0].market,dossiers:ds.map(d=>({...d,structure:structural(state,d),filedCurrent:d.stateLabel==='RECORDED_FILING'?d.facts.map(old=>{const current=state.fields.filter(f=>f.parameter===old.parameter&&f.batch===old.batch&&f.product===old.product&&f.status==='APPROVED').filter(f=>{try{fact(state,{fieldId:f.id,revision:f.revision});return true;}catch{return false;}});return {fieldId:old.fieldId,recorded:old,current:current.map(f=>descriptor(state,{fieldId:f.id,revision:f.revision})),divergent:!current.some(f=>f.value===old.value&&context(f)===context(old))};}):[]})),globalMarketCoverage:false}));}
function riskCandidates(state){const risks=[];for(const d of selected(state,'dossiers')){const check=structural(state,d);for(const c of check.coverage.filter(c=>!c.covered))risks.push({id:`prediction:${d.id}:${c.requirementId}`,question:`What controlled evidence supports ${c.parameter} in section ${d.section}?`,basis:{dossierId:d.id,requirementId:c.requirementId,revision:c.revision,availableCount:c.availableCount,requiredCount:c.requiredCount,sourceCitations:c.sourceCitations},state:'PREDICTION',probability:null,notAHistoricalAuthorityQuestion:true});if(d.status==='STALE')risks.push({id:`prediction:${d.id}:stale`,question:`Which current source revisions support the recorded ${d.section} statements?`,basis:{dossierId:d.id,issues:d.issues},state:'PREDICTION',probability:null,notAHistoricalAuthorityQuestion:true});}for(const c of dossierConsistency(state).filter(x=>x.scientificValueConflict||x.contextConflict))risks.push({id:`prediction:${c.key}:consistency`,question:`How are the recorded ${c.parameter} differences reconciled across dossier sections?`,basis:c,state:'PREDICTION',probability:null,notAHistoricalAuthorityQuestion:true});return {candidates:risks,trainedModel:false,interpretation:'Transparent gap/rule-derived query candidates, not actual regulator questions or calibrated risk probabilities.'};}
function closureProjection(state){const e=hydrateLifecycle(state);return selected(state,'closures').map(a=>{const v=e.verifications.findLast(v=>v.closureId===a.id&&v.passed),checks=closureChecks(state,a),invalid=a.status==='STALE'||checks.some(c=>!c.passed);return {...a,verification:v?copy(v):null,checks,actionStatus:v?(invalid?'REOPENED':'CLOSED_WITH_EVIDENCE'):'OPEN',continuousScheduler:'NOT_CONFIGURED',scope:'Source-change-triggered and on-demand checks, no autonomous clinical/regulatory effectiveness claim.'};});}
